import { MakeLogicType, afterMount, connect, kea, path } from 'kea'
import { loaders } from 'kea-loaders'

import { projectLogic } from 'scenes/projectLogic'

import { llmSkillsList } from 'products/skills/frontend/generated/api'
import type { LLMSkillListApi } from 'products/skills/frontend/generated/api.schemas'

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface taskSkillsPickerLogicValues {
    currentProjectId: number | null // projectLogic
    skills: LLMSkillListApi[]
    skillsLoading: boolean
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface taskSkillsPickerLogicActions {
    loadSkills: () => any
    loadSkillsFailure: (
        error: string,
        errorObject?: any
    ) => {
        error: string
        errorObject?: any
    }
    loadSkillsSuccess: (
        skills: LLMSkillListApi[],
        payload?: any
    ) => {
        skills: LLMSkillListApi[]
        payload?: any
    }
}

export type taskSkillsPickerLogicType = MakeLogicType<taskSkillsPickerLogicValues, taskSkillsPickerLogicActions>

export const taskSkillsPickerLogic = kea<taskSkillsPickerLogicType>([
    path(['products', 'tasks', 'frontend', 'components', 'TaskSkillsPicker', 'taskSkillsPickerLogic']),
    connect(() => ({
        values: [projectLogic, ['currentProjectId']],
    })),
    loaders(({ values }) => ({
        skills: [
            [] as LLMSkillListApi[],
            {
                loadSkills: async (): Promise<LLMSkillListApi[]> => {
                    // Most teams keep well under this many skills; MAX_BUNDLE_SKILLS on the
                    // backend caps a single bundle at 100, so that's the ceiling here too.
                    const response = await llmSkillsList(String(values.currentProjectId), { limit: 100 })
                    return response.results
                },
            },
        ],
    })),
    afterMount(({ actions }) => {
        actions.loadSkills()
    }),
])
